/// `orient2d`'s exact value in width-aware limbs (chapter 23.3): each step in `i64`, or in a
/// `Wide32` of as many 32-bit limbs as its operands' certified bits need, with checked arithmetic,
/// and the result in the shipped path's type; `None` only if a step overflowed, which the
/// certificate rules out.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    reason = "each name is a step of the description, named by the language's rule"
)]
pub fn orient2d_value(a: P2, b: P2, c: P2) -> Option<i128> {
    let ba_x = b.x.get().checked_sub(a.x.get())?;
    let ba_y = b.y.get().checked_sub(a.y.get())?;
    let ca_x = c.x.get().checked_sub(a.x.get())?;
    let ca_y = c.y.get().checked_sub(a.y.get())?;
    let det_1 = Wide32::<3>::product_i64(ba_x, ca_y)?;
    let det_2 = Wide32::<3>::product_i64(ba_y, ca_x)?;
    let det = det_1.checked_sub(&det_2)?;
    det.to_i128()
}

/// `orient3d`'s exact value in width-aware limbs (chapter 23.3): each step in `i64`, or in a
/// `Wide32` of as many 32-bit limbs as its operands' certified bits need, with checked arithmetic,
/// and the result in the shipped path's type; `None` only if a step overflowed, which the
/// certificate rules out.
