pub fn incircle_value(a: P2, b: P2, c: P2, d: P2) -> Option<I256> {
    let ad_x = a.x.get().checked_sub(d.x.get())?;
    let ad_y = a.y.get().checked_sub(d.y.get())?;
    let bd_x = b.x.get().checked_sub(d.x.get())?;
    let bd_y = b.y.get().checked_sub(d.y.get())?;
    let cd_x = c.x.get().checked_sub(d.x.get())?;
    let cd_y = c.y.get().checked_sub(d.y.get())?;
    let a_lift_1 = Wide32::<3>::product_i64(ad_x, ad_x)?;
    let a_lift_2 = Wide32::<3>::product_i64(ad_y, ad_y)?;
    let a_lift = a_lift_1.checked_add(&a_lift_2)?;
    let b_lift_1 = Wide32::<3>::product_i64(bd_x, bd_x)?;
    let b_lift_2 = Wide32::<3>::product_i64(bd_y, bd_y)?;
    let b_lift = b_lift_1.checked_add(&b_lift_2)?;
    let c_lift_1 = Wide32::<3>::product_i64(cd_x, cd_x)?;
    let c_lift_2 = Wide32::<3>::product_i64(cd_y, cd_y)?;
    let c_lift = c_lift_1.checked_add(&c_lift_2)?;
    let bc_1 = Wide32::<3>::product_i64(bd_x, cd_y)?;
    let bc_2 = Wide32::<3>::product_i64(bd_y, cd_x)?;
    let bc = bc_1.checked_sub(&bc_2)?;
    let ca_1 = Wide32::<3>::product_i64(cd_x, ad_y)?;
    let ca_2 = Wide32::<3>::product_i64(cd_y, ad_x)?;
    let ca = ca_1.checked_sub(&ca_2)?;
    let ab_1 = Wide32::<3>::product_i64(ad_x, bd_y)?;
    let ab_2 = Wide32::<3>::product_i64(ad_y, bd_x)?;
    let ab = ab_1.checked_sub(&ab_2)?;
    let det_1 = Wide32::<6>::product(&a_lift, &bc)?;
    let det_2 = Wide32::<6>::product(&b_lift, &ca)?;
    let det_3 = det_1.checked_add(&det_2)?;
    let det_4 = Wide32::<6>::product(&c_lift, &ab)?;
    let det = det_3.checked_add(&det_4)?;
    det.to_wide::<4>()
}

